from pathlib import Path
import json

# ১) আসল SciFact Sample 0-এ Top-10 Candidate Shortlist ও Ceiling যাচাই
root = Path("assets/datasets/scifact_rag")
lab = json.loads((root / "rag_lab.json").read_text(encoding="utf-8"))

sample = lab["samples"][0]
run = sample["cases"]["rerank"]
candidate_ids = []
for pair in run["retrieved"]:
    candidate_ids.append(pair[0])

assert len(candidate_ids) <= 10
gold_ids = list(sample["evidence"].keys())

gold_in_shortlist = False
for gid in gold_ids:
    if gid in candidate_ids:
        gold_in_shortlist = True

selected_ids = []
for chunk in run["selected"]:
    selected_ids.append(chunk["doc_id"])

gold_in_packed = False
for gid in gold_ids:
    if gid in selected_ids:
        gold_in_packed = True

print("Sample 0 gold doc:", gold_ids, "| In Top-10:", gold_in_shortlist, "| In Packed:", gold_in_packed)
print("Top-5 retrieved IDs:", candidate_ids[:5])

# ২) হাতে-কলমে ৪-Document Funnel ও Ceiling অসমতা যাচাই
gold_set = {"101", "205", "309", "412"}
top10_set = {"101", "205", "309", "888"}
packed_set = {"101", "309"}

avail_hits = 0
final_hits = 0
for g in gold_set:
    if g in top10_set:
        avail_hits += 1
    if g in packed_set:
        final_hits += 1

avail = avail_hits / len(gold_set)
final_rec = final_hits / len(gold_set)
assert final_rec <= avail
print(f"Toy Ceiling={avail:.2f}, Final={final_rec:.2f}, Invariant(final<=ceiling)={final_rec <= avail}")

def compute_evidence_metrics(selected_chunks, evidence_dict):
    # ১) Gold Qualified Sentence সেট তৈরি: (doc_id, sent_idx)
    gold_union = set()
    alternatives = []
    for doc_id in evidence_dict:
        for ann in evidence_dict[doc_id]:
            alt_set = set()
            for s_idx in ann["sentences"]:
                pair = (doc_id, s_idx)
                gold_union.add(pair)
                alt_set.add(pair)
            alternatives.append(alt_set)

    # Annotation না থাকলে None ফেরত (কখনোই 0 নয়!)
    if len(gold_union) == 0:
        return None

    # ২) Selected Context থেকে Unique Qualified Sentences বের করা
    present = set()
    for chunk in selected_chunks:
        for s_idx in range(chunk["start"], chunk["end"]):
            present.add((chunk["doc_id"], s_idx))

    overlap_count = 0
    for pair in present:
        if pair in gold_union:
            overlap_count += 1

    union_recall = overlap_count / len(gold_union)
    complete_hit = 0
    for alt in alternatives:
        if alt <= present:
            complete_hit = 1
            break

    return {"union_recall": union_recall, "complete_hit": complete_hit}

# পরীক্ষা ১: বিকল্প Rationale ({7:0} অথবা {7:1, 7:2}) — শুধু [7:0-1] এসেছে
ev1 = {"7": [{"sentences": [0]}, {"sentences": [1, 2]}]}
m1 = compute_evidence_metrics([{"doc_id": "7", "start": 0, "end": 1}], ev1)
assert m1["complete_hit"] == 1 and abs(m1["union_recall"] - 1.0 / 3.0) < 1e-9
print("Test 1 (Alt rationale) :", m1)

# পরীক্ষা ২: Doc ID না রাখলে ভুয়া সাফল্য (A:0, C:0 বনাম {A:0,A:1} বা {B:0})
ev2 = {"A": [{"sentences": [0, 1]}], "B": [{"sentences": [0]}]}
chunks2 = [{"doc_id": "A", "start": 0, "end": 1}, {"doc_id": "C", "start": 0, "end": 1}]
m2 = compute_evidence_metrics(chunks2, ev2)
# ভুল (Collapsed) হিসাব দেখাচ্ছি:
collapsed_ctx = {0}
false_hit = 1 if ({0} <= collapsed_ctx) else 0
print(f"Test 2 (Doc ID bug)    : true_recall={m2['union_recall']:.4f}, true_hit={m2['complete_hit']}, BUGGY_collapsed_hit={false_hit}")

# পরীক্ষা ৩: Missing annotation -> None ও Empty context -> 0
assert compute_evidence_metrics(chunks2, {}) is None
m_empty = compute_evidence_metrics([], ev1)
assert m_empty["complete_hit"] == 0 and m_empty["union_recall"] == 0.0
print("Test 3 (Edge cases)    : missing_ann=None OK | empty_ctx=", m_empty)

